<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class AssistanceDistribution extends Model {protected $fillable=['application_id','supply_batch_id','reference','operation_key','quantity','status','processed_by','distributed_at']; protected $casts=['quantity'=>'decimal:2','distributed_at'=>'datetime']; public function application(){return $this->belongsTo(AssistanceApplication::class,'application_id');} public function batch(){return $this->belongsTo(SupplyBatch::class,'supply_batch_id');} public function processor(){return $this->belongsTo(User::class,'processed_by');} public function inventoryMovement(){return $this->belongsTo(InventoryMovement::class,'reference','reference');}}
